import{_ as e,o as l,c as a,a2 as d}from"./chunks/framework.D66Xq0Kv.js";const M=JSON.parse('{"title":"展开链讲稿 · 第五分册：与标准理论的关系与涨落伴丛","description":"","frontmatter":{},"headers":[],"relativePath":"L005_第五分册_与标准理论的关系与涨落伴丛.md","filePath":"L005_第五分册_与标准理论的关系与涨落伴丛.md"}'),n={name:"L005_第五分册_与标准理论的关系与涨落伴丛.md"};function r(o,t,s,i,g,h){return l(),a("div",null,[...t[0]||(t[0]=[d('<div><h1 id="展开链讲稿-·-第五分册-与标准理论的关系与涨落伴丛" tabindex="-1">展开链讲稿 · 第五分册：与标准理论的关系与涨落伴丛 <a class="header-anchor" href="#展开链讲稿-·-第五分册-与标准理论的关系与涨落伴丛" aria-label="Permalink to &quot;展开链讲稿 · 第五分册：与标准理论的关系与涨落伴丛&quot;">​</a></h1><blockquote><p><strong>稿子性质</strong>：本稿是<strong>撰写</strong>，不是摘录。它接续第四分册（超导涌现链），处理两类问题： CQM 与四块标准理论各自是什么关系（退化、取消还是消解），以及耦合常数的涨落在数学上落在哪里（纤维丛）。</p><p><strong>它不是权威源</strong>。权威源仍是各文档原文与根 <code>README.md</code>；本稿的每一条论断都在<strong>附录 A</strong> 里钉到出处。</p><p><strong>三条写作纪律</strong>（本稿对 <code>AGENTS.md</code> 三条红线的具体执行）：</p><ol><li><strong>不欺骗</strong>——未证处不得写成已证。凡&quot;退化&quot;&quot;还原&quot;只写原文写了的条件；凡取消与消解，只写原文给出的论证结构，不替原文补强。</li><li><strong>不绕过</strong>——缺口不省略、不用&quot;因此&quot;跨过；必须跨时，句式是&quot;在缺口 X 未闭合的前提下，下游成立的是……&quot;。</li><li><strong>不虚构</strong>——只用原文已有的概念、术语、数值与关系；不引入原文未涉及的观点，也不替原文补理由（原文未展开动机处，本稿明写&quot;原文未在此处展开&quot;）。</li></ol></blockquote><hr><h2 id="卷首-·-本分册在链条上的位置" tabindex="-1">卷首 · 本分册在链条上的位置 <a class="header-anchor" href="#卷首-·-本分册在链条上的位置" aria-label="Permalink to &quot;卷首 · 本分册在链条上的位置&quot;">​</a></h2><p>第四分册的终点是&quot;超导态作为晶胞量子振荡全局相干模式涌现&quot;。本册退后一步，问两个元问题：第一，这条链与既有的标准理论是什么关系——它替代谁、退化到谁、取消谁、消解谁（第一至四章）；第二，链条上反复出现的&quot;结构群&quot;&quot;伴丛&quot;&quot;涨落&quot;到底是什么意思（第五、六章）。最后第七章把全链收口成一张图。</p><table tabindex="0"><thead><tr><th style="text-align:left;">层</th><th style="text-align:left;">省略什么</th><th style="text-align:left;">回答什么</th><th style="text-align:left;">在哪章</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>导读层</strong></td><td style="text-align:left;">省略全部构造细节</td><td style="text-align:left;">CQM 对 BCS 是退化，对贝尔是取消，对测量问题是消解——三个词不能混用</td><td style="text-align:left;">第一、三、四章前半</td></tr><tr><td style="text-align:left;"><strong>概念层</strong></td><td style="text-align:left;">省略证明，保留对象与对应</td><td style="text-align:left;">退化对应表、四个隐藏预设、伴丛族、结构群叠加态</td><td style="text-align:left;">第一、三、五、六章</td></tr><tr><td style="text-align:left;"><strong>链条层</strong></td><td style="text-align:left;">不省略顺序，标注状态与断点</td><td style="text-align:left;">RG 流的&quot;惊险一跃&quot;在哪；群从哪里来</td><td style="text-align:left;">第二章、第七章</td></tr><tr><td style="text-align:left;"><strong>技术层</strong></td><td style="text-align:left;">不省略任何东西</td><td style="text-align:left;">传输方程、路径积分、Elitzur/Fradkin–Shenker 文献标注</td><td style="text-align:left;">指向原文 §12、§13</td></tr></tbody></table><hr><h2 id="第一章-与-bcs-退化-而不是竞争" tabindex="-1">第一章 与 BCS：退化，而不是竞争 <a class="header-anchor" href="#第一章-与-bcs-退化-而不是竞争" aria-label="Permalink to &quot;第一章 与 BCS：退化，而不是竞争&quot;">​</a></h2><h3 id="_1-1-退化对应表" tabindex="-1">1.1 退化对应表 <a class="header-anchor" href="#_1-1-退化对应表" aria-label="Permalink to &quot;1.1 退化对应表&quot;">​</a></h3><p>原文对 BCS 的关系是<strong>退化与还原</strong>：CQM 超导框架在特定极限下退化为 BCS 理论。对应关系与原表照录：【锚 A-55】</p><table tabindex="0"><thead><tr><th style="text-align:left;">CQM 对象</th><th style="text-align:left;">BCS 对应</th><th style="text-align:left;">退化条件</th></tr></thead><tbody><tr><td style="text-align:left;">角亏涨落 $\\Delta\\delta_v$</td><td style="text-align:left;">声子振幅</td><td style="text-align:left;">弱引力极限 $\\beta\\delta_v\\to0$</td></tr><tr><td style="text-align:left;">固有时流速 $d\\tau/dt$</td><td style="text-align:left;">晶胞量子振荡周期</td><td style="text-align:left;">平直极限 $\\delta_v\\to0$</td></tr><tr><td style="text-align:left;">耦合常数跃迁 $\\alpha\\to n^2\\alpha$</td><td style="text-align:left;">能隙打开</td><td style="text-align:left;">自由能交叉附近线性化</td></tr><tr><td style="text-align:left;">和乐相位闭合条件</td><td style="text-align:left;">相位相干性</td><td style="text-align:left;">长波极限</td></tr></tbody></table><p>读表的方式与第二分册的常数表一样：每一行都是一个<strong>条件</strong>。退化不是自动的，是取极限的结果。</p><h3 id="_1-2-两个特例" tabindex="-1">1.2 两个特例 <a class="header-anchor" href="#_1-2-两个特例" aria-label="Permalink to &quot;1.2 两个特例&quot;">​</a></h3><p>原文还给了两个具体的退化实例：<strong>普适能隙比</strong>——BCS 的 $2\\Delta(0)/k_BT_c=3.53$ 在 CQM 中对应于跃迁耦级 $2\\ln n$ 的固定尺度比（$n=2$ 退化为 $\\ln4$）；<strong>同位素效应</strong>——BCS 的 $T_c\\propto M^{-1/2}$ 在 CQM 中由主次结构谱间隙差驱动（中子扇区质量效应）。【锚 A-55】</p><p>同位素效应这一行同时是一条桥：它把本册接回第四分册的缺口带——&quot;主次结构谱间隙差 → 同位素效应映射&quot;正是缺口 G15（未闭合）。</p><hr><h2 id="第二章-与重整化群-同一个方程-不同的本体论" tabindex="-1">第二章 与重整化群：同一个方程，不同的本体论 <a class="header-anchor" href="#第二章-与重整化群-同一个方程-不同的本体论" aria-label="Permalink to &quot;第二章 与重整化群：同一个方程，不同的本体论&quot;">​</a></h2><h3 id="_2-1-方程与解" tabindex="-1">2.1 方程与解 <a class="header-anchor" href="#_2-1-方程与解" aria-label="Permalink to &quot;2.1 方程与解&quot;">​</a></h3><p>CQM 的 RG 流由带 $e^u$ 因子的非线性传输方程描述：</p><p>$$\\partial_\\tau\\phi+v\\,e^u\\partial_u\\phi=0$$</p><p>其特征线 $du/d\\tau=ve^u$（即 $dr/d\\tau=vr^2$，$r=e^u=g^2$）的解为有理函数：</p><p>$$r(\\tau)=\\frac{1}{-v\\tau+C}$$</p><p>原文的判断很硬：此形式与标准 QFT 单圈 RG 流 $dg/dt=-\\beta_0g^3$ <strong>完全一致</strong>——若令 $\\tau\\leftrightarrow\\ln(\\mu/\\Lambda)$，则 $g^2\\sim1/\\ln(\\mu/\\Lambda)$，即标准的对数跑动。【锚 A-56】</p><h3 id="_2-2-同一个方程-不同的本体论" tabindex="-1">2.2 同一个方程，不同的本体论 <a class="header-anchor" href="#_2-2-同一个方程-不同的本体论" aria-label="Permalink to &quot;2.2 同一个方程，不同的本体论&quot;">​</a></h3><p>原文紧接着把本体论分歧摆开（这是本章的要害，删掉任何一半都会失真）：【锚 A-56】</p><ul><li><strong>标准 QFT</strong>：RG 流是路径积分标度变换的数学结果，能标 $\\mu$ 是外部参数；</li><li><strong>CQM</strong>：RG 流是单质子内禀时钟驱动的非线性传输，能标被因果时 $\\tau$ 取代。</li></ul><p><strong>流动方向</strong>：因果时 $\\tau$ 从 UV 流向 IR（因果演化方向），耦合随 $\\tau$ 增大而增大（IR 端耦合变强），与 QCD 渐近自由方向一致——UV 端耦合弱，IR 端耦合强。原文并注明：<strong>RG 流属于禁闭边界及之外的物理</strong>（高能标/UV 区域，耦合常数跑动描述能标依赖）。</p><h3 id="_2-3-断点-惊险一跃" tabindex="-1">2.3 断点：惊险一跃 <a class="header-anchor" href="#_2-3-断点-惊险一跃" aria-label="Permalink to &quot;2.3 断点：惊险一跃&quot;">​</a></h3><blockquote><p><strong>断点（就地标出）</strong>：CQM <strong>尚未完成</strong>从第一性原理计算具体耦合常数跑动曲线的定量推导——原文称之为&quot;<strong>惊险一跃</strong>&quot;（未闭合）。因此本章给出的只是&quot;形式一致 + 本体论分歧&quot;，不是&quot;已算出的跑动曲线&quot;：方程的解形与单圈 QFT 一致，但 CQM 一侧的曲线本身还没从第一性原理走出来。【锚 A-56】</p></blockquote><hr><h2 id="第三章-与贝尔不等式-不是违反-是取消" tabindex="-1">第三章 与贝尔不等式：不是违反，是取消 <a class="header-anchor" href="#第三章-与贝尔不等式-不是违反-是取消" aria-label="Permalink to &quot;第三章 与贝尔不等式：不是违反，是取消&quot;">​</a></h2><h3 id="_3-1-四个隐藏预设" tabindex="-1">3.1 四个隐藏预设 <a class="header-anchor" href="#_3-1-四个隐藏预设" aria-label="Permalink to &quot;3.1 四个隐藏预设&quot;">​</a></h3><p>本章的标题句就是原文的黑体：<strong>贝尔不等式不是被 CQM 违反的——它是被 CQM 取消的。</strong> 原文先把贝尔原始推导的隐藏预设摆成四条：【锚 A-57】</p><ol><li><strong>共同概率空间</strong>：$\\lambda$ 对所有测量设置是同一变量；</li><li><strong>联合分布存在</strong>：$\\rho(\\lambda)$ 是良定义的概率测度；</li><li><strong>因子化</strong>：$P(a,b\\vert\\lambda)=P(a\\vert\\lambda)P(b\\vert\\lambda)$；</li><li><strong>因果可达</strong>：$\\lambda$ 必须能被测量设置&quot;访问&quot;。</li></ol><h3 id="_3-2-cqm-的回应" tabindex="-1">3.2 CQM 的回应 <a class="header-anchor" href="#_3-2-cqm-的回应" aria-label="Permalink to &quot;3.2 CQM 的回应&quot;">​</a></h3><p>原文对四条预设逐条回应：【锚 A-57】</p><ul><li>不存在对全部物理系统共同的变量——不同物理系统的&quot;隐变量&quot;是不同组织形式；</li><li>因果不可达的事件之间不存在联合概率分布；</li><li>因子化预设了子系统的独立存在性——CQM 中&quot;两个粒子&quot;不是独立子系统，而是全局因果网络的不同节点；</li><li>因果结构本身因果不可达，因此不存在&quot;访问&quot;关系。<strong>因果结构不是隐变量</strong>——&quot;变量&quot;预设了可赋值、可分离的存在形式，而因果结构是使&quot;隐藏/显现&quot;之分成为可能的本体论基底，不是被隐藏的存在者。</li></ul><h3 id="_3-3-fine-定理与跨尺度论证" tabindex="-1">3.3 Fine 定理与跨尺度论证 <a class="header-anchor" href="#_3-3-fine-定理与跨尺度论证" aria-label="Permalink to &quot;3.3 Fine 定理与跨尺度论证&quot;">​</a></h3><p>原文援引 <strong>Fine 定理</strong>：贝尔不等式成立 $\\iff$ 存在一个联合概率分布覆盖所有不可同时测量的可观测量。在 CQM 中，Alice 和 Bob 的测量设备是物理系统核/原子尺度的宏观物体，纠缠粒子是物理系统费米尺度的系统。<strong>不存在一个跨尺度的联合概率分布</strong>——因为费米尺度的 $\\lambda_{L1}$ 和宏观尺度的 $\\lambda_{L3}$ 不是同一数学空间中的变量。【锚 A-57】</p><p>结论句必须整句保留：<strong>因此，贝尔不等式在 CQM 中不仅被&quot;违反&quot;——它根本不被定义。</strong></p><p>本稿的读法提醒（不是原文论断）：&quot;不被定义&quot;比&quot;被违反&quot;更强也更弱——它不宣称量子关联消失，只宣称推导贝尔不等式的概率舞台本身不存在。原文未在此处进一步讨论这与实验检验的关系，本稿不补。</p><hr><h2 id="第四章-与测量问题-不是解决-是消解" tabindex="-1">第四章 与测量问题：不是解决，是消解 <a class="header-anchor" href="#第四章-与测量问题-不是解决-是消解" aria-label="Permalink to &quot;第四章 与测量问题：不是解决，是消解&quot;">​</a></h2><h3 id="_4-1-只存在系统命运" tabindex="-1">4.1 只存在系统命运 <a class="header-anchor" href="#_4-1-只存在系统命运" aria-label="Permalink to &quot;4.1 只存在系统命运&quot;">​</a></h3><p>传统量子力学的&quot;测量问题&quot;：波函数何时坍缩？由什么触发？CQM 的回应是一句话：<strong>不存在测量问题，只存在系统命运。</strong> 原文用一张表把四个过程与传统术语对上：【锚 A-58】</p><table tabindex="0"><thead><tr><th style="text-align:left;">过程</th><th style="text-align:left;">CQM 描述</th><th style="text-align:left;">传统术语</th></tr></thead><tbody><tr><td style="text-align:left;">系统诞生</td><td style="text-align:left;">前核子自组织确立禁闭边界，物理系统边界局部非幺正确立</td><td style="text-align:left;">&quot;量子→经典过渡&quot;</td></tr><tr><td style="text-align:left;">系统维持</td><td style="text-align:left;">系统内部条件性幺正运行，再生产闭环</td><td style="text-align:left;">&quot;幺正演化&quot;</td></tr><tr><td style="text-align:left;">系统跃迁</td><td style="text-align:left;">弱相互作用导致味空间再分配</td><td style="text-align:left;">&quot;衰变&quot;</td></tr><tr><td style="text-align:left;">系统消亡</td><td style="text-align:left;">电磁吸收，条件性幺正消亡，边界消解</td><td style="text-align:left;">&quot;测量/坍缩&quot;</td></tr></tbody></table><h3 id="_4-2-关键在区分" tabindex="-1">4.2 关键在区分 <a class="header-anchor" href="#_4-2-关键在区分" aria-label="Permalink to &quot;4.2 关键在区分&quot;">​</a></h3><p>原文对这张表的总结只有一句：传统理论将不同物理系统的因果过程混为一谈，导致&quot;测量问题&quot;；CQM 通过<strong>系统—尺度—层级递进本体论</strong>将它们严格区分。【锚 A-58】</p><p>本稿对&quot;消解&quot;一词的读法（依据原文结构）：坍缩没有被解释，而是被拆成了四个不同层级的事件；拆完之后，&quot;何时坍缩&quot;这个问题没有残留的指涉对象。这是消解，不是解决。</p><hr><h2 id="第五章-纤维丛-耦合常数的涨落落在哪里" tabindex="-1">第五章 纤维丛：耦合常数的涨落落在哪里 <a class="header-anchor" href="#第五章-纤维丛-耦合常数的涨落落在哪里" aria-label="Permalink to &quot;第五章 纤维丛：耦合常数的涨落落在哪里&quot;">​</a></h2><h3 id="_5-1-海森堡代数的一维性限定" tabindex="-1">5.1 海森堡代数的一维性限定 <a class="header-anchor" href="#_5-1-海森堡代数的一维性限定" aria-label="Permalink to &quot;5.1 海森堡代数的一维性限定&quot;">​</a></h3><p>原文第一步是给耦合常数涨落指定结构群：</p><p>$$u_G=\\ln g_G,\\qquad[u_G,p_{u_G}]=i$$</p><p>其中 $G$ <strong>明确指定</strong>结构群。原文的限定紧接着出现：$u_G=\\ln g_G$ 作为全局单坐标定义，<strong>当且仅当</strong> $G$ 是一维阿贝尔群（$S^1$ 及其商 $U(1)//\\mathbb Z_n$）；非阿贝尔群的对数是局部且多值的（Baker–Campbell–Hausdorff 级数），无法定义单一海森堡对。因此耦合常数的海森堡量子化<strong>只在电磁扇区直接可行</strong>：【锚 A-59】</p><ul><li>超导：$U(1)_{\\text{em}}$，涨落 $u_{U(1)}$，跃迁耦级 $2\\ln n$，资格条件（第四分册 §3.4）；</li><li>核子同位旋 $SU(2)_{\\text{isospin}}$ 与色动力学 $SU(3)_{\\text{color}}$：耦合常数<strong>不经</strong>海森堡代数直接量子化，而是经 Casimir 阶梯 $g_k=\\alpha^{-1}\\exp(-(n_k-n_1)/n_1)$ 从 $U(1)$ 锚导出（重整化群跑动形式）。</li></ul><h3 id="_5-2-耦合常数唯一-荷多样化" tabindex="-1">5.2 耦合常数唯一，荷多样化 <a class="header-anchor" href="#_5-2-耦合常数唯一-荷多样化" aria-label="Permalink to &quot;5.2 耦合常数唯一，荷多样化&quot;">​</a></h3><p>每个结构群只有一个耦合常数：</p><p>$$D_\\mu=\\partial_\\mu-ig_GA_\\mu^aT^a$$</p><p>荷是表示矩阵 $T^a$ 的本征值，多种多样。有效荷 $=g_G\\times q_R$。CQM 中涨落的是唯一耦合常数 $g_G$，<strong>不是</strong>多样的荷。耦合常数跃迁时，该扇区所有荷同步改变。【锚 A-60】</p><h3 id="_5-3-条件而非唯一确定" tabindex="-1">5.3 条件而非唯一确定 <a class="header-anchor" href="#_5-3-条件而非唯一确定" aria-label="Permalink to &quot;5.3 条件而非唯一确定&quot;">​</a></h3><p>耦合常数涨落不能<strong>唯一确定</strong>伴丛的结构群，只能<strong>限定</strong>它。条件是分层的：【锚 A-61】</p><p>$$\\underbrace{[\\hat u,\\hat p_u]=i}_{\\text{条件}_1}\\;\\to\\;\\underbrace{U(1)}_{\\substack{\\text{条件}_1\\text{产物}\\\\\\text{=条件}_2\\text{对象}}}\\;\\xrightarrow{\\;\\mathbb Z_n\\text{ 商}\\;}\\;\\underbrace{U(1)//\\mathbb Z_n}_{\\substack{\\text{条件}_2\\text{产物}\\\\\\text{=丛构造输入}}}\\;\\to\\;\\underbrace{E_n}_{\\text{产物}}$$</p><ul><li><strong>条件$_1$</strong>：海森堡代数一维性 → 结构群必须一维阿贝尔 → 产物 $U(1)$；</li><li><strong>条件$_2$</strong>：$\\mathbb Z_n$（电荷量子化：权 $q$ 表示当且仅当 $n\\mid q$ 时下降）商限定 $U(1)$ → 产物 $U(1)//\\mathbb Z_n$；</li><li><strong>丛构造</strong>：每个 $U(1)//\\mathbb Z_n$ 给出伴丛 $E_n=P\\times_{G_n}\\mathbb C$。</li></ul><h3 id="_5-4-涨落伴丛" tabindex="-1">5.4 涨落伴丛 <a class="header-anchor" href="#_5-4-涨落伴丛" aria-label="Permalink to &quot;5.4 涨落伴丛&quot;">​</a></h3><p>原文对&quot;涨落伴丛&quot;的定义有一个容易读错的词：它是<strong>伴丛族</strong>（不是群族——承载序参量的是伴丛，不是群集合）：</p><p>$$\\mathcal E_{\\text{涨落}}=\\{E_n=P\\times_{G_n}\\mathbb C\\mid G_n\\in\\mathcal G\\},\\qquad\\mathcal G=\\{U(1)//\\mathbb Z_n\\mid n\\text{ 偶}\\}$$</p><p>圈定候选群族的是<strong>三重条件</strong>：① 和乐李代数条件（由 $\\Delta u_G$ 给出，限定 $\\mathfrak{hol}\\subseteq\\mathfrak g$）；② 底空间拓扑条件（陈类、离散对称性、边界条件）；③ 物质场表示条件（序参量属于哪个表示，凝聚后保持哪个子群不变）。三重条件圈定候选群族，不唯一决定；路径积分在<strong>伴丛族</strong>上选出主导伴丛 $E_{n^*}$——<strong>选群的目的是选丛</strong>。【锚 A-62】</p><h3 id="_5-5-先在规范直积群" tabindex="-1">5.5 先在规范直积群 <a class="header-anchor" href="#_5-5-先在规范直积群" aria-label="Permalink to &quot;5.5 先在规范直积群&quot;">​</a></h3><p>$$G_0=U(1)\\times SU(2)\\times SU(3)$$</p><p>是物质自组织的基态规范骨架，<strong>不可还原</strong>。物质在先在规范群的基础上，通过晶胞角亏、固有时流速、耦合空间涨落，展开出具体层级的伴丛结构。物质在某个层级看到的伴丛结构群 $=G_0$ 经过所有扇区耦合涨落改造后的<strong>剩余结构</strong>。【锚 A-63】</p><hr><h2 id="第六章-对称性叠加-相变-对称性退相干" tabindex="-1">第六章 对称性叠加：相变 = 对称性退相干 <a class="header-anchor" href="#第六章-对称性叠加-相变-对称性退相干" aria-label="Permalink to &quot;第六章 对称性叠加：相变 = 对称性退相干&quot;">​</a></h2><h3 id="_6-1-结构群本身叠加了" tabindex="-1">6.1 结构群本身叠加了 <a class="header-anchor" href="#_6-1-结构群本身叠加了" aria-label="Permalink to &quot;6.1 结构群本身叠加了&quot;">​</a></h3><p>原文把这一点称为 CQM 的核心突破：<strong>结构群本身叠加了。</strong> 传统量子力学叠加&quot;状态&quot;，CQM 叠加&quot;对称性&quot;：</p><p>$$\\vert\\Psi_{\\text{对称性}}\\rangle=\\sum_{G\'\\in\\mathcal G}c_{G\'}\\,\\vert G\'\\rangle$$</p><p>旧量子场论：粒子态可以叠加，但结构群固定；CQM：结构群本身处于叠加态，由角亏涨落与温度决定哪个群被宏观实现。【锚 A-64】</p><h3 id="_6-2-相变不是破缺" tabindex="-1">6.2 相变不是破缺 <a class="header-anchor" href="#_6-2-相变不是破缺" aria-label="Permalink to &quot;6.2 相变不是破缺&quot;">​</a></h3><p>$$\\vert\\Psi_{\\text{对称性}}\\rangle=c_1\\vert U(1)\\rangle+c_2\\vert\\{e\\}\\rangle+c_3\\vert\\mathbb Z_2\\rangle+\\cdots$$</p><p>正常态 $c_1$ 占主导；超导态 $c_2$ 或 $c_3$ 占主导；临界点叠加最完整、两组权重相等。原文的结论句：<strong>相变不是&quot;破缺&quot;，而是结构群叠加态的退相干。</strong>【锚 A-64】</p><h3 id="_6-3-大统一的新解读" tabindex="-1">6.3 大统一的新解读 <a class="header-anchor" href="#_6-3-大统一的新解读" aria-label="Permalink to &quot;6.3 大统一的新解读&quot;">​</a></h3><p>原文由此给出对大统一的重新定位，这段话包含全部分寸，本稿整段照录：$GL(5)$ 是真正的宇宙大统一群（约化李群，非紧致），本身是<strong>重组实现</strong>的，不是破缺的。<strong>就物理相变而言：破缺的必须是非规范对称群（或更一般地，非规范对称性），但非规范对称群不一定破缺；重组实现的既可以是规范对称群，也可以是非规范对称群；而规范对称群相变必然是重组，而非破缺。</strong> 早期宇宙中规范群可能处于更复杂的叠加态，随宇宙冷却，某些群被淘汰，最终留下 $U(1)\\times SU(2)\\times SU(3)$。$SU(5)$ 重组实现给出标准模型因子（结构群叠加退相干结果，不是破缺）；$GL(5,\\mathbb R)$ 的时空对称性若纳入规范群则必须破缺。$GL(5)$ 本身是物质更前面的自组织的产物。【锚 A-65】</p><p>原文为此附了文献标注（规范对称性不破缺的外部依据）：局域规范对称性不能自发破缺——Elitzur 定理（Elitzur 1975, <em>Phys. Rev. D</em> 12, 3978）；Higgs 相与禁闭区之间无热力学奇异线，规范对称性不作为相变序参量（Fradkin–Shenker 1979, <em>Phys. Rev. D</em> 19, 3682）。CQM 的重组实现立场与此定理相容。【锚 A-65】</p><h3 id="_6-4-与量子群-量子丛的区分" tabindex="-1">6.4 与量子群/量子丛的区分 <a class="header-anchor" href="#_6-4-与量子群-量子丛的区分" aria-label="Permalink to &quot;6.4 与量子群/量子丛的区分&quot;">​</a></h3><p>原文用一张表把新概念与最易混的旧概念分开：【锚 A-66】</p><table tabindex="0"><thead><tr><th style="text-align:left;">量子群</th><th style="text-align:left;">CQM 涨落伴丛</th></tr></thead><tbody><tr><td style="text-align:left;">把群数学形变为 Hopf 代数</td><td style="text-align:left;">群仍是经典李群</td></tr><tr><td style="text-align:left;">量子性来自形变参数 $q$</td><td style="text-align:left;">量子性来自角亏涨落 $\\Delta\\delta_v$</td></tr><tr><td style="text-align:left;">数学柏拉图主义</td><td style="text-align:left;">物质自组织结果</td></tr><tr><td style="text-align:left;">低能不可见</td><td style="text-align:left;">超导中直接检验</td></tr></tbody></table><p>结论一句：涨落伴丛不是量子群，是 CQM 的独立新概念。</p><h3 id="_6-5-群是计算结果" tabindex="-1">6.5 群是计算结果 <a class="header-anchor" href="#_6-5-群是计算结果" aria-label="Permalink to &quot;6.5 群是计算结果&quot;">​</a></h3><p>原文对超导群多样性的解释只有一句：<strong>超导群之所以多样，是因为物质条件丰富。</strong> 路径积分自动选出主导群，无需人为指定：【锚 A-67】</p><table tabindex="0"><thead><tr><th style="text-align:left;">条件</th><th style="text-align:left;">主导超导群</th></tr></thead><tbody><tr><td style="text-align:left;">角亏低，序参量标量 $q=2$</td><td style="text-align:left;">$U(1)\\to\\{e\\}$ 或 $U(1)//\\mathbb Z_2$（s 波）</td></tr><tr><td style="text-align:left;">角亏各向异性，序参量在 $SO(2)$ 下变号</td><td style="text-align:left;">$U(1)\\times SO(2)\\to\\mathbb Z_2$（d 波）</td></tr><tr><td style="text-align:left;">角亏含自旋扇区，序参量为自旋三重态</td><td style="text-align:left;">$U(1)\\times SU(2)\\to H_{\\text{spin}}$（p 波）</td></tr><tr><td style="text-align:left;">角亏强且和乐非平庸</td><td style="text-align:left;">拓扑超导群，马约拉纳零模</td></tr></tbody></table><p>四个字的结论：<strong>群是计算结果。</strong> 原文对此的总括（§13.13）：CQM 从&quot;使用纤维丛语言描述物质自组织&quot;走向&quot;对称性本身的量子力学&quot;；不是数学预设对称性然后让物质服从，而是物质自己生成、叠加、选择并实现对称性。<strong>群不是上帝的设计图，而是物质历史运动的轨迹。</strong></p><hr><h2 id="第七章-收口-一条统一链条" tabindex="-1">第七章 收口：一条统一链条 <a class="header-anchor" href="#第七章-收口-一条统一链条" aria-label="Permalink to &quot;第七章 收口：一条统一链条&quot;">​</a></h2><h3 id="_7-1-完整统一链条" tabindex="-1">7.1 完整统一链条 <a class="header-anchor" href="#_7-1-完整统一链条" aria-label="Permalink to &quot;7.1 完整统一链条&quot;">​</a></h3><p>原文把全案收口成一条链（本稿照录）：【锚 A-68】</p><p>$$\\text{物质}\\to\\text{SU(5) 基态同步（GL(5) 紧化，GRH）}\\to\\text{ζ 零点谱（GL(1) 电磁因子层，黎曼猜想）}\\to A_4\\text{ 有限化}\\to\\text{先在规范群}\\to\\text{结构群叠加态}\\to\\text{路径积分选择}\\to\\text{具体超导群}$$</p><p>分层要点与第三分册第五章一致：基态同步是 SU(5)（GL(5) 自守形式经紧化算符投影）；黎曼猜想是 GL(5) 固定层级的实谱条件；<strong>物质自组织选中 GL(5)（SU(5) 是含标准模型的最小单群，rank 4）正是物质自组织的体现</strong>；$n>5$ 层级不排除，但 GL(5) 主导物理谱。</p><h3 id="_7-2-质数—群对应" tabindex="-1">7.2 质数—群对应 <a class="header-anchor" href="#_7-2-质数—群对应" aria-label="Permalink to &quot;7.2 质数—群对应&quot;">​</a></h3><p>原文给了一张质数/数学结构与群结构的对应表（照录）：【锚 A-68】</p><table tabindex="0"><thead><tr><th style="text-align:left;">质数/数学结构</th><th style="text-align:left;">群结构</th></tr></thead><tbody><tr><td style="text-align:left;">质数作为不可约生成元</td><td style="text-align:left;">有限群 Sylow 定理</td></tr><tr><td style="text-align:left;">GL(5) 基态自守零点谱 → SU(5) 基态同步；ζ 零点谱直接作为 GL(5) 固定层级下使用的谱</td><td style="text-align:left;">$A_4$ 根空间谱</td></tr><tr><td style="text-align:left;">$1,2,3$</td><td style="text-align:left;">$U(1),SU(2),SU(3)$</td></tr><tr><td style="text-align:left;">4-单纯形组合</td><td style="text-align:left;">$S_5$ Weyl 群</td></tr><tr><td style="text-align:left;">有限域</td><td style="text-align:left;">表示论</td></tr></tbody></table><h3 id="_7-3-扇区化表现形式" tabindex="-1">7.3 扇区化表现形式 <a class="header-anchor" href="#_7-3-扇区化表现形式" aria-label="Permalink to &quot;7.3 扇区化表现形式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">扇区</th><th style="text-align:left;">底空间角亏</th><th style="text-align:left;">耦合常数</th><th style="text-align:left;">跃迁耦级/资格条件</th><th style="text-align:left;">限定出的结构群族</th></tr></thead><tbody><tr><td style="text-align:left;">$U(1)_{\\text{em}}$</td><td style="text-align:left;">$\\delta_v^{\\text{cell}}$</td><td style="text-align:left;">$\\alpha$</td><td style="text-align:left;">$2\\ln n$（$n=2,4,6,\\ldots$）</td><td style="text-align:left;">$\\{e\\},\\mathbb Z_2,U(1)//\\mathbb Z_2,\\ldots$</td></tr><tr><td style="text-align:left;">$SU(2)_{\\text{isospin}}$</td><td style="text-align:left;">$\\delta_v^{\\text{nuc}}$</td><td style="text-align:left;">$g_2$</td><td style="text-align:left;">待定</td><td style="text-align:left;">$SU(2)\\to H_{\\text{核}}$</td></tr><tr><td style="text-align:left;">$SU(3)_{\\text{color}}$</td><td style="text-align:left;">$\\delta_v^{\\text{nuc}}$</td><td style="text-align:left;">$\\alpha_s$</td><td style="text-align:left;">禁闭阈值</td><td style="text-align:left;">禁闭态结构</td></tr></tbody></table><p>注意第二、三行的&quot;待定&quot;与&quot;禁闭阈值&quot;：只有电磁扇区走到了跃迁耦级谱，另两个扇区的跃迁规则原文未给出——这是现状，不是省略。【锚 A-69】</p><h3 id="_7-4-四条总结" tabindex="-1">7.4 四条总结 <a class="header-anchor" href="#_7-4-四条总结" aria-label="Permalink to &quot;7.4 四条总结&quot;">​</a></h3><p>原文对全案的总结四条（照录）：<strong>对称性不是先验的</strong>，是物质自组织的历史产物；<strong>群不是上帝的设计图</strong>，是物质运动的轨迹；<strong>质数不是纯数学对象</strong>，是不可约生成元；<strong>黎曼猜想不是孤立谜题</strong>，是广义黎曼猜想在 GL(1)（电磁因子）的特例，是物质自组织在电磁因子层的稳定性条件；<strong>超导群不是理论家选的</strong>，是物质自己在条件下实现的。【锚 A-68】</p><hr><h2 id="附录-a-·-锚点表" tabindex="-1">附录 A · 锚点表 <a class="header-anchor" href="#附录-a-·-锚点表" aria-label="Permalink to &quot;附录 A · 锚点表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">锚</th><th style="text-align:left;">论断摘要</th><th style="text-align:left;">出处</th><th style="text-align:left;">定位</th><th style="text-align:left;">核对状态</th></tr></thead><tbody><tr><td style="text-align:left;">A-55</td><td style="text-align:left;">BCS 退化对应表；普适能隙比 $3.53\\leftrightarrow\\ln4$；同位素效应由主次结构谱间隙差驱动</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td><td style="text-align:left;">§12.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-56</td><td style="text-align:left;">RG 传输方程与解、与单圈 QFT 一致、$\\tau\\leftrightarrow\\ln(\\mu/\\Lambda)$、本体论分歧、UV→IR 方向、&quot;RG 流属于禁闭边界及之外的物理&quot;、&quot;惊险一跃&quot;未完成</td><td style="text-align:left;">同上</td><td style="text-align:left;">§12.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-57</td><td style="text-align:left;">贝尔不等式被取消；四个隐藏预设；四条回应；&quot;因果结构不是隐变量&quot;；Fine 定理；跨尺度无联合分布；&quot;根本不被定义&quot;</td><td style="text-align:left;">同上</td><td style="text-align:left;">§12.3</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-58</td><td style="text-align:left;">测量问题消解；四过程表；系统—尺度—层级递进本体论</td><td style="text-align:left;">同上</td><td style="text-align:left;">§12.4</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-59</td><td style="text-align:left;">海森堡代数一维性限定；电磁扇区直接可行；$SU(2)/SU(3)$ 经 Casimir 阶梯导出</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-60</td><td style="text-align:left;">耦合常数唯一、荷多样化；有效荷 $=g_G\\times q_R$；涨落的是 $g_G$</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-61</td><td style="text-align:left;">条件分层：条件$_1$/条件$_2$/丛构造；&quot;不能唯一确定，只能限定&quot;</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.3</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-62</td><td style="text-align:left;">涨落伴丛＝伴丛族（不是群族）；三重条件；选群的目的是选丛</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.4</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-63</td><td style="text-align:left;">先在规范直积群 $G_0$ 不可还原；剩余结构</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.5</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-64</td><td style="text-align:left;">结构群叠加；相变＝对称性退相干；三态权重</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.9、§13.11</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-65</td><td style="text-align:left;">大统一新解读（GL(5) 重组实现；规范对称群相变必然是重组而非破缺）；Elitzur 1975、Fradkin–Shenker 1979 文献标注</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.11</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-66</td><td style="text-align:left;">与量子群/量子丛区分表</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.12</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-67</td><td style="text-align:left;">超导群多样性表（s/d/p/拓扑）；&quot;群是计算结果&quot;</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.14</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-68</td><td style="text-align:left;">完整统一链条；分层要点；质数—群对应表；四条总结</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.15、§13.17</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-69</td><td style="text-align:left;">扇区化表现形式表（含&quot;待定&quot;与&quot;禁闭阈值&quot;）</td><td style="text-align:left;">同上</td><td style="text-align:left;">§13.7</td><td style="text-align:left;">逐字核对</td></tr></tbody></table><h2 id="附录-b-·-六关自检-本稿口径" tabindex="-1">附录 B · 六关自检（本稿口径） <a class="header-anchor" href="#附录-b-·-六关自检-本稿口径" aria-label="Permalink to &quot;附录 B · 六关自检（本稿口径）&quot;">​</a></h2><p>沿用第一分册附录 B 的六关：出处存在／对象正确／段落相关／论断被支撑／<strong>限定语保留</strong>／来源适配。本分册的限定语集中在四处，写作时逐处核对：</p><ol><li>BCS 退化的&quot;<strong>特定极限下</strong>&quot;——四行对应表每行都带退化条件，不可读成无条件等价（A-55）；</li><li>RG 的&quot;<strong>形式一致 + 本体论分歧 + 惊险一跃未完成</strong>&quot;三层并存——只取其一即失真（A-56）；</li><li>大统一解读的&quot;<strong>规范对称群相变必然是重组，而非破缺</strong>&quot;及其外部文献标注——Elitzur/Fradkin–Shenker 是原文引用的相容性依据，不是 CQM 自证（A-65）；</li><li>扇区表的&quot;<strong>待定</strong>&quot;——$SU(2)$ 跃迁耦级原文未给出，不得补全（A-69）。</li></ol><h2 id="附录-c-·-下一分册" tabindex="-1">附录 C · 下一分册 <a class="header-anchor" href="#附录-c-·-下一分册" aria-label="Permalink to &quot;附录 C · 下一分册&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">分册</th><th style="text-align:left;">覆盖链条段</th><th style="text-align:left;">主要依据</th></tr></thead><tbody><tr><td style="text-align:left;">第六分册</td><td style="text-align:left;">量纲发生学专章（$K$ 家族逐项、自守形式猜想、锚点与检验）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_量纲与群论.md</code> §六、§七</td></tr></tbody></table></div>',1)])])}const f=e(n,[["render",r]]);export{M as __pageData,f as default};
